const bq = (id: string, cat: InterviewCat, level: 1 | 2 | 3 | 4, concept: string, question: string, a: string, reasoning: string, trap: string, topics: string[]): BankQuestion => ({ id, cat, q: question, level, concept, a, reasoning, trap, topics });

export const EXTRA_BANK: BankQuestion[] = [
  bq("eb-reset-main", "firmware", 2, "Startup", "What happens from reset to main() on a Cortex-M?", "Hardware loads MSP from vector 0 and PC from vector 1; Reset_Handler copies .data from flash to RAM, zeroes .bss, runs SystemInit (clocks, FPU), runs static constructors, then calls main.", "C assumes initialised globals and zeroed statics; startup code provides that.", "Forgetting the .data copy or saying the OS loads the program.", ["emb-linker-startup"]),
  bq("eb-vector", "firmware", 1, "Vector table", "What is in the vector table?", "Initial stack pointer, then handler addresses for reset, NMI, faults, SVC, PendSV, SysTick and each device interrupt.", "The core indexes the table by exception number.", "Omitting the initial stack pointer entry.", ["emb-exceptions"]),
  bq("eb-volatile", "firmware", 2, "volatile", "Why is volatile required for registers and ISR flags, and when is it not enough?", "It forces every access to be emitted. It does not make read-modify-write atomic, does not order memory for DMA or other cores, and does not protect multi-word data.", "The optimizer may cache or remove accesses without it.", "Calling volatile thread-safe.", ["emb-c-bits", "emb-interrupts"]),
  bq("eb-irq-entry", "firmware", 3, "Exception entry", "What happens during interrupt entry on Cortex-M?", "Priority check, stacking of R0-R3, R12, LR, PC, xPSR (plus FPU state if active), vector fetch, LR = EXC_RETURN, switch to Handler mode on MSP, jump to handler.", "Hardware stacking lets handlers be plain C functions.", "Saying the CPU saves all registers.", ["emb-exceptions"]),
  bq("eb-why-dma", "firmware", 2, "DMA", "Why use DMA, and why can DMA corrupt data?", "To move data without CPU work per byte, reducing load, jitter and power. Corruption comes from cache incoherence, buffers processed while DMA writes them, stack buffers going out of scope and misalignment.", "DMA and CPU are two bus masters sharing memory.", "Only listing the benefits.", ["emb-dma"]),
  bq("eb-mutex-sem", "rtos", 2, "Synchronisation", "How does a mutex differ from a semaphore?", "Mutex: ownership, released by the holder, usually priority inheritance, for mutual exclusion. Semaphore: no owner, used for signalling or counting resources, can be given from ISRs.", "Different intents lead to different kernel features.", "Calling a binary semaphore a mutex.", ["emb-rtos-sync"]),
  bq("eb-prio-inv", "rtos", 3, "Priority inversion", "What is priority inversion and how is it fixed?", "High-priority task waits on a mutex held by a low-priority task that is preempted by medium tasks. Fix with priority inheritance or ceiling, shorter critical sections, or no sharing.", "Unbounded blocking breaks real-time guarantees (Mars Pathfinder, 1997).", "Suggesting 'raise the high task's priority further'.", ["emb-rtos-sync"]),
  bq("eb-stack-size", "rtos", 3, "Stack sizing", "How do you calculate a task's stack size?", "Estimate deepest call chain locals plus exception stacking (32 bytes, 104 with FPU context) plus library use; measure the high-water mark under worst case; add 25-50% margin; use -fstack-usage for call graphs.", "Stacks are static budgets; overflow corrupts neighbours silently.", "Picking 1 KB for every task.", ["emb-freertos", "emb-faults"]),
  bq("eb-hardfault", "firmware", 3, "Fault analysis", "How do you debug a HardFault?", "Read HFSR and CFSR, fault address registers, determine MSP/PSP from EXC_RETURN, read stacked PC/LR, map with addr2line, reproduce; make imprecise faults precise if needed.", "The core records cause and context; use them.", "Only stepping through code.", ["emb-faults"]),
  bq("eb-wdt", "firmware", 2, "Watchdog", "Why does a watchdog reset happen and how do you avoid false confidence?", "The watchdog was not refreshed in time. Kick only when all tasks have checked in, not from a timer ISR, and log the reset cause and a breadcrumb.", "A timer-ISR kick keeps a hung system 'alive'.", "Kicking from SysTick.", ["emb-wdt-flash"]),
  bq("eb-i2c-lock", "firmware", 3, "I2C recovery", "How do you debug and fix an I2C bus lock?", "Observe SDA held low; switch pins to GPIO, clock SCL up to nine times until SDA is released, send STOP, reinitialise; add timeouts and boot-time recovery.", "A slave interrupted mid-byte keeps driving SDA.", "Only resetting the MCU's I2C peripheral.", ["emb-spi-i2c"]),
  bq("eb-linker", "firmware", 2, "Linker scripts", "What does a linker script do?", "Defines memory regions and places input sections into output sections at addresses, sets load versus run addresses (.data), exports symbols for startup code and reserves stack/heap.", "Firmware has no loader; addresses are fixed at link time.", "Saying it 'links libraries'.", ["emb-linker-startup"]),
  bq("eb-bootloader", "firmware", 2, "Bootloaders", "What is a bootloader and how does it start the application?", "Code that validates and optionally updates firmware, then disables interrupts, resets peripherals, sets VTOR, loads MSP from the app's vector table and jumps to its reset handler.", "It must hand over a clean CPU state.", "Forgetting VTOR and MSP.", ["emb-bootloader"]),
  bq("eb-ota-rollback", "firmware", 3, "OTA", "How does OTA rollback work with MCUboot?", "The new image boots in test mode and must confirm itself; if not confirmed before the next reset, the bootloader swaps back. A security counter blocks deliberate downgrades.", "Test-then-confirm makes updates recoverable.", "Assuming the bootloader can judge app health by itself.", ["emb-ota"]),
  bq("eb-secure-boot", "firmware", 2, "Secure boot", "What are secure boot and a root of trust?", "Each stage verifies the signature of the next, anchored in immutable code and fused keys that are trusted without verification: the root of trust.", "Trust must start somewhere that cannot be modified.", "Equating CRC checks with secure boot.", ["emb-security"]),
  bq("eb-buildroot-yocto", "emblinux", 2, "Build systems", "Buildroot or Yocto?", "Buildroot: simple, fast, single image. Yocto: layered, scalable, SDKs, package feeds, SBOM and compliance, much steeper and heavier. Yocto 6.0 uses bitbake-setup; the poky repo is deprecated.", "Match tool complexity to product-line needs.", "Saying one is simply 'better'.", ["emb-buildroot", "emb-yocto"]),
  bq("eb-devicetree", "emblinux", 2, "Device tree", "How does the device tree work?", "A hardware description (nodes and properties) compiled to a DTB and passed by the bootloader; the kernel creates devices from nodes and binds drivers by compatible strings.", "It separates board description from driver code.", "Saying drivers read the DTS source file.", ["emb-devicetree"]),
  bq("eb-bind", "emblinux", 3, "Driver binding", "How does a Linux driver bind to hardware, and what is a platform driver?", "The bus matches devices and drivers; for SoC peripherals, platform devices from DT nodes match drivers via of_match_table compatible strings and probe() is called. A platform driver handles non-discoverable memory-mapped devices.", "Matching and probe are the device model's core.", "Confusing module loading with binding.", ["emb-linux-drivers"]),
  bq("eb-boot-chain", "emblinux", 2, "Boot chain", "Describe the embedded Linux boot chain.", "Boot ROM, first-stage loader (SPL, often with TF-A on arm64), U-Boot, kernel plus DTB (plus initramfs), init, root filesystem services.", "Each stage initialises just enough for the next.", "Skipping the DTB.", ["emb-linux-boot"]),
  bq("en-uart", "firmware", 1, "Numerical: UART", "At 9600 baud 8N1, how long does a 64-byte message take?", "10 bits per byte: 640 bits / 9600 = 66.7 ms.", "Start and stop bits count.", "Using 8 bits per byte.", ["emb-uart"]),
  bq("en-timer", "firmware", 2, "Numerical: timer", "A 16-bit timer runs at 1 MHz. What is its overflow period, and how do you measure a 200 ms pulse?", "65536 us = 65.5 ms, so count overflows in software or prescale to 100 kHz (655 ms range, 10 us resolution).", "Range = 2^N / f_tick.", "Ignoring overflow.", ["emb-timers"]),
  bq("en-adc-rate", "firmware", 2, "Numerical: sampling", "Four ADC channels at 10 kHz each, 12-bit samples in 16-bit words, processed every 10 ms with double buffering. Buffer size and interrupt rate?", "Per half: 4 x 100 x 2 bytes = 800 bytes; total 1600 bytes; one half-complete interrupt every 10 ms, i.e. 100 interrupts per second.", "Size buffers from rate x period.", "Forgetting the second half of the double buffer.", ["emb-dma", "emb-adc"]),
  bq("en-cpu-irq", "firmware", 2, "Numerical: interrupt load", "An ISR takes 2 us and fires at 50 kHz. What CPU fraction does it use?", "2 us x 50,000/s = 0.1 s per second: 10% of the CPU, before entry/exit overhead.", "Utilisation = time per event x rate.", "Ignoring entry overhead at high rates.", ["emb-interrupts", "emb-realtime"]),
  bq("en-can", "firmware", 3, "Numerical: CAN timing", "CAN clock 80 MHz, 500 kbit/s. Choose prescaler and segments for an 87.5% sample point.", "Prescaler 10 gives 8 MHz time quanta, 16 tq per bit: sync 1, prop+phase1 13, phase2 2; sample point (1 + 13) / 16 = 87.5%.", "Bit time = tq count x tq period.", "Forgetting the sync segment.", ["emb-can"]),
  bq("en-rms", "rtos", 3, "Numerical: schedulability", "Tasks (C, T) in ms: (2, 10), (3, 15), (5, 30). Schedulable under RMS?", "U = 0.2 + 0.2 + 0.167 = 0.567 < 0.780 (3-task bound): yes.", "The Liu-Layland bound is sufficient, not necessary.", "Using the bound as a necessary test.", ["emb-realtime"]),
  bq("en-battery", "firmware", 2, "Numerical: battery", "Sensor: 8 mA for 100 ms every 60 s, 4 uA otherwise, 1200 mAh battery. Life?", "I_avg = 8 x 0.1/60 + 0.004 x 59.9/60 = 0.0133 + 0.0040 = 0.0173 mA; 1200 / 0.0173 = about 69,000 h, roughly 7.9 years before derating.", "Average current over one period.", "Ignoring sleep current.", ["emb-power"]),
];

