export const EXTRA_PRACTICE: PracticeItem[] = [
  { id: "pr-mtbf", title: "MTBF of one versus two synchronizer flops", type: "timing", level: "intermediate", phase: "p5",
    prompt: "tau = 30 ps, T0 = 50 ps, f_clk = 1 GHz, f_data = 100 MHz, setup overhead 0.1 ns. Compute MTBF with one resolving cycle (t_r = 0.9 ns) and with a second flop (t_r = 1.9 ns). MTBF = e^(t_r / tau) / (T0 * f_clk * f_data).",
    hints: ["Compute the denominator once: 50e-12 x 1e9 x 1e8.", "e^30 is about 1.07e13."],
    solution: "Denominator = 5e6 per second. One flop: e^30 / 5e6 = about 2.1e6 s, roughly 25 days: unacceptable. Two flops: e^63.3 / 5e6 = about 6e20 s, roughly 2e13 years. Each extra resolution cycle multiplies MTBF by e^(T/tau).",
    topics: ["metastability", "cdc"] },
  { id: "pr-pulse-sync", title: "Crossing a single-cycle pulse from fast to slow clock", type: "rtl", level: "intermediate", phase: "p5",
    prompt: "A 1-cycle pulse in a 200 MHz domain must be seen exactly once in a 50 MHz domain. Why does a 2-flop synchronizer fail, and what do you build instead?",
    hints: ["Could the slow clock miss the pulse entirely?", "Convert the event into a level change."],
    solution: "The pulse (5 ns) can fall between slow edges (20 ns) and be missed. Use a toggle synchronizer: toggle a flop on each pulse in the source domain, synchronize the level with two flops, and XOR successive synchronized values to regenerate one pulse. Events must be spaced at least about three destination cycles apart, or use a handshake or async FIFO.",
    topics: ["cdc"] },
  { id: "pr-emb-baud", title: "UART divisor and error budget", type: "timing", level: "beginner", phase: "e3",
    prompt: "Peripheral clock 48 MHz, oversampling by 16. Compute the divisor and error for 115200 and 921600 baud. Are both usable for 8N1?",
    hints: ["divisor = f_clk / baud with this style of peripheral.", "Keep total error well under about 2%."],
    solution: "115200: 416.67, round to 417, actual 115108, error -0.08%: fine. 921600: 52.08, round to 52, actual 923077, error +0.16%: fine. Check the other end's error too.",
    topics: ["emb-uart"] },
  { id: "pr-emb-timer", title: "Timer and PWM register values", type: "timing", level: "beginner", phase: "e3",
    prompt: "Timer clock 84 MHz. Configure a 10 kHz periodic interrupt, then 25 kHz PWM with 40% duty on another timer. Give PSC, ARR and CCR.",
    hints: ["f = f_clk / ((PSC + 1)(ARR + 1)).", "Pick PSC first for a round tick."],
    solution: "10 kHz: PSC = 83 (1 MHz), ARR = 99. 25 kHz PWM: PSC = 0, ARR = 3359 (84e6 / 25e3 = 3360), CCR = 1344 (40%).",
    topics: ["emb-timers"] },
  { id: "pr-emb-dma", title: "Sizing a DMA double buffer", type: "architecture", level: "intermediate", phase: "e4",
    prompt: "An audio codec streams stereo 16-bit samples at 48 kHz over I2S. Processing runs every 5 ms. Size a circular DMA double buffer and state the interrupt rate and deadline.",
    hints: ["Samples per 5 ms per channel?", "Half-transfer and complete each mark one half."],
    solution: "240 frames x 2 channels x 2 bytes = 960 bytes per half, 1920 bytes total; one interrupt every 5 ms (200 per second); processing each half must finish within 5 ms including worst-case jitter.",
    topics: ["emb-dma"] },
  { id: "pr-emb-fault", title: "Decode the fault status registers", type: "debug", level: "advanced", phase: "e5",
    prompt: "After a crash: HFSR = 0x40000000, CFSR = 0x00020000, stacked PC = 0x00000000, LR = 0x08001235. What happened and what do you check in the code?",
    hints: ["HFSR bit 30 is FORCED.", "UFSR bits start at CFSR bit 16; bit 17 is INVSTATE."],
    solution: "A usage fault escalated to HardFault (FORCED). INVSTATE: execution tried to leave Thumb state, typically calling a null or even-address function pointer; PC = 0 confirms a call through a null pointer. LR 0x08001235 points just after the call site: addr2line it and check the callback registration.",
    topics: ["emb-faults"] },
  { id: "pr-emb-rms", title: "Is this task set schedulable?", type: "thinking", level: "intermediate", phase: "e6",
    prompt: "Tasks (C, T) ms: A (1, 5), B (2, 10), C (4, 20), D (3, 40). Check with the RMS bound, then with response-time analysis for task D.",
    hints: ["U = sum C/T.", "R_D = C_D + sum ceil(R_D / T_j) C_j over higher-priority tasks."],
    solution: "U = 0.2 + 0.2 + 0.2 + 0.075 = 0.675 < 0.757 (4-task bound): schedulable. Response-time analysis for D: R0 = 3 + 1 + 2 + 4 = 10; R1 = 3 + ceil(10/5)x1 + ceil(10/10)x2 + ceil(10/20)x4 = 11; R2 = 3 + 3 + 4 + 4 = 14; R3 = 14 (converged). 14 ms is within D's 40 ms deadline.",
    topics: ["emb-realtime"] },
  { id: "pr-emb-stack", title: "Estimate a task stack", type: "debug", level: "intermediate", phase: "e6",
    prompt: "A task's deepest call chain uses 120, 80 and 256 bytes of locals; it calls snprintf (budget 400 bytes); the core has an FPU and the task uses floats. Estimate the stack and describe how to verify it.",
    hints: ["Exception stacking with FPU context is 104 bytes.", "Add a margin."],
    solution: "456 + 400 + 104 = 960 bytes; with a 30% margin, about 1.25 KB. Verify with stack painting / uxTaskGetStackHighWaterMark under worst-case load and -fstack-usage output; enable the overflow hook in debug builds.",
    topics: ["emb-freertos", "emb-faults"] },
];

